                if (Creature* jikun = me->GetCreature(*me, pInstance->GetGuidData(NPC_JI_KUN)))
                {
                    me->SetFacingToObject(jikun);
                    events.RescheduleEvent(EVENT_FALLCATCHER_IN_POS, 500);
                }
                break;
            case 2:
                if (Vehicle* fallcatcher = me->GetVehicleKit())
                {
